n":"Quels éléments existants faut-il impérativement conserver ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-367","sort_order":1,"variable":"reponse_1","question":"Quelle destination et quelle ambiance souhaitez-vous ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-368","sort_order":1,"variable":"reponse_1","question":"S’agit-il d’une inspiration libre ou d’un projet contraint par un terrain et un budget ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-368","sort_order":2,"variable":"reponse_2","question":"Quelles pièces et contraintes sont indispensables ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-369","sort_order":1,"variable":"reponse_1","question":"Quels trois goûts ou activités doivent être visibles dans la pièce ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-370","sort_order":1,"variable":"reponse_1","question":"Quels univers souhaitez-vous comparer ou dois-je choisir quatre contrastes cohérents ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-371","sort_order":1,"variable":"reponse_1","question":"Quelles époques souhaitez-vous comparer ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-372","sort_order":1,"variable":"reponse_1","question":"Quels nom, capacités ou statistiques exacts doivent apparaître ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-373","sort_order":1,"variable":"reponse_1","question":"Quelle mini-histoire ou progression doit relier les quatre poses ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-374","sort_order":1,"variable":"reponse_1","question":"Quelle matière et quel type de lieu doivent accueillir la statue ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-375","sort_order":1,"variable":"reponse_1","question":"Souhaitez-vous une fresque réaliste, graphique ou communautaire ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-376","sort_order":1,"variable":"reponse_1","question":"Préférez-vous un hologramme réaliste, scénique ou cybernétique ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-377","sort_order":1,"variable":"reponse_1","question":"Quel type de créature et quelle humeur souhaitez-vous ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-378","sort_order":1,"variable":"reponse_1","question":"Faut-il seulement décrire ce qui est visible ou intégrer des références et prix vérifiés ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-379","sort_order":1,"variable":"reponse_1","question":"Quel matériel et combien de sources lumineuses sont disponibles ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-379","sort_order":2,"variable":"reponse_2","question":"Quelles sont les dimensions ou limites de l’espace ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-380","sort_order":1,"variable":"reponse_1","question":"Quelle durée, quel format et quel objectif doit servir la vidéo ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"},{"ref":"RCI-IMG-380","sort_order":2,"variable":"reponse_2","question":"Quels lieux, personnes et matériels sont réellement disponibles ?","trigger_note":"Après analyse, seulement si cette information influence le livrable et reste inconnue"}]$raccourcia$::jsonb) as d(
  ref text, sort_order smallint, variable text, question text, trigger_note text
)
join public.prompts p on p.external_ref = d.ref and p.catalog_version = 'v5.1'
where not exists (
  select 1 from public.prompt_questions q
  where q.prompt_id = p.id and q.sort_order = d.sort_order
);

do $ctrl$
declare
  v_total integer;
begin
  select count(*) into v_total
  from public.prompt_questions q
  join public.prompts p on p.id = q.prompt_id and p.catalog_version = 'v5.1';
  if v_total <> 68 then
    raise exception 'Lot 800 : % questions au lieu de 68.', v_total;
  end if;

  -- Le plafond annonce doit valoir ce que la commande peut poser.
  select count(*) into v_total
  from public.prompts p
  where p.catalog_version = 'v5.1'
    and coalesce(p.max_questions, 0)
        <> (select count(*) from public.prompt_questions q where q.prompt_id = p.id);
  if v_total > 0 then
    raise exception '% commandes de l''extension annoncent un plafond faux.', v_total;
  end if;
end $ctrl$;
